const isAR = () => !!(window.I18N && window.I18N.isAR);
const L = (en, ar) => (isAR() ? ar : en);
const TX = (o, k) => (o ? ((isAR() && o[k + "Ar"]) ? o[k + "Ar"] : (o[k] || "")) : "");
// Any thrown value -> a friendly line in the active language (ApiError carries both).
const errMsg = (e) => (e && typeof e.friendly === "function" ? e.friendly(isAR()) : (e && e.message) || String(e || ""));
let HIDE = false; const setHide = (v) => { HIDE = !!v; };   // public (type-only) links: no prices anywhere
const SAR = (n) => (HIDE ? "" : "SAR " + D.fmtSAR(n || 0));
