const stepsFor = (project) => { const f = (project && project.features) || {}; return STEP_DEFS.filter((s) => !s.needs || f[s.needs]); };
const emptyDraft = () => ({ designId: null, paletteId: null, packageId: null, smartId: null, opsId: null, fitout: false, kitchenId: null, kitchenPaletteId: null, kitchenScope: "cabinets", kitchenAddons: [], acId: null, acAddons: [], flooring: {}, layoutIds: [], beneficiary: false, skip: {} });
