    kitchenId: d.kitchen ? d.kitchen.id : null, kitchenPaletteId: d.kitchen ? cfg.kitchenPaletteId : null, kitchenScope: d.kitchen ? (cfg.kitchenScope || "cabinets") : null, kitchenAddons: d.kitchen ? (cfg.kitchenAddons || []) : [], kitchenCost: d.kitchenNet * VAT,
