  useEffect(() => { const h = () => refresh(); const pull = () => { if (document.visibilityState === "visible") D.refresh(["orders", "units", "orderActivity", "documents"].concat(D.REMOTE_KEYS)).then(h, () => {}); }; const t = setInterval(pull, 15000); return () => clearInterval(t); }, []);
  const isMgr = D.devHasPerm(me, "team"); const teamIds = isMgr && scope === "team" ? R.sellersOf(developer.id).map((u) => u.id).concat(me.id) : [me.id]; const inScope = (id) => teamIds.includes(id);
  const subs = R.submissions().filter((s) => inScope(s.repId)); const pending = subs.filter((s) => s.status === "pending"); const links = R.links().filter((l) => l.mode !== "type" && inScope(l.repId)); const notes = R.notifications(me.id).filter((n) => !n.readAt);
