        {rep && rep.mobile && <a className="pw-ghost" target="_blank" rel="noopener" href={R.wa(rep.mobile, L("Hello " + repName + ", I've sent my order (ref " + code + ").", "السلام عليكم " + repName + "، أرسلت طلبي ورقم المرجع " + code + "."))}>{L("WhatsApp " + repName, "تواصل مع " + repName + " على واتساب")}</a>}
